using ExamGateway.Extensions;var builder=WebApplication.CreateBuilder(args);builder.Services.AddGateway(builder.Configuration);var app=builder.Build();app.UseSwagger();app.UseSwaggerUI(o=>{o.SwaggerEndpoint("/swagger/v1/swagger.json","WAEC API Gateway V1");o.SwaggerEndpoint("/swagger/auth/v1/swagger.json","Authentication Service");o.SwaggerEndpoint("/swagger/catalog/v1/swagger.json","Catalog Service");o.SwaggerEndpoint("/swagger/orders/v1/swagger.json","Orders Service");o.SwaggerEndpoint("/swagger/registration/v1/swagger.json","Registration Service");o.RoutePrefix="swagger";});app.UseAuthentication();app.UseAuthorization();app.MapGet("/health",()=>Results.Ok(new{service="gateway",status="healthy"}));app.MapReverseProxy();app.Run();